=اليوم هو {{ $now.setZone('Asia/Riyadh').toFormat('yyyy-MM-dd') }} بتوقيت الرياض.

حلّل جملة المحاسبة التالية واستخرج منها الحقول المطلوبة:

{{ $json.body.text }}

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "amount": {
      "type": "number",
      "description": "المبلغ الرقمي فقط بدون رمز العملة. حوّل الأرقام العربية الهندية إلى أرقام إنجليزية. مثال: 20"
    },
    "currency": {
      "type": "string",
      "description": "رمز العملة بمعيار ISO. ريال أو ريال سعودي = SAR، دولار = USD، درهم = AED. إذا لم تُذكر عملة استخدم SAR"
    },
    "direction": {
      "type": "string",
      "enum": ["expense", "income"],
      "description": "expense للصرف والدفع والشراء والسداد. income للدخل والقبض والاستلام والبيع"
    },
    "category": {
      "type": "string",
      "enum": ["مواد خام", "رواتب", "نقل", "إيجار", "مرافق", "تسويق", "معدات", "صيانة", "ضيافة", "رسوم", "أخرى"],
      "description": "أقرب تصنيف للحركة. إذا لم يتضح التصنيف اختر أخرى"
    },
    "vendor": {
      "type": "string",
      "description": "اسم الجهة أو المحل أو الشخص كما ورد في النص. اتركه نصاً فارغاً إذا لم يُذكر"
    },
    "spent_at": {
      "type": "string",
      "description": "تاريخ الحركة بصيغة YYYY-MM-DD، محسوباً بالنسبة لتاريخ اليوم المذكور في بداية النص. أمس يعني اليوم ناقص يوم. إذا لم يُذكر تاريخ استخدم تاريخ اليوم"
    },
    "note": {
      "type": "string",
      "description": "وصف مختصر جداً لما تم صرفه أو سبب الحركة"
    }
  },
  "required": ["amount", "direction", "category", "spent_at"]
}

parameters.jsCode:
const body = $('استقبال الطلب').first().json.body ?? {};
const _raw = $input.first().json ?? {};
const ext = (_raw.output && typeof _raw.output === 'object') ? _raw.output : _raw;
const zone = 'Asia/Riyadh';

const raw = String(body.text ?? '').trim();

let amount = Number(ext.amount);
if (!Number.isFinite(amount) || amount <= 0) {
  throw new Error('ما قدرت أفهم المبلغ من الجملة. جرّب صيغة مثل: صرفت 20 ريال عند المصنع');
}
amount = Math.round(amount * 100) / 100;

let spent = DateTime.fromISO(String(ext.spent_at ?? ''), { zone });
if (!spent.isValid) spent = DateTime.now().setZone(zone);

const allowed = ['مواد خام', 'رواتب', 'نقل', 'إيجار', 'مرافق', 'تسويق', 'معدات', 'صيانة', 'ضيافة', 'رسوم', 'أخرى'];
const category = allowed.includes(ext.category) ? ext.category : 'أخرى';
const direction = ext.direction === 'income' ? 'income' : 'expense';
const currency = String(ext.currency || 'SAR').toUpperCase().slice(0, 3);

return [{
  json: {
    spent_at: spent.startOf('day').toISO(),
    amount,
    currency,
    direction,
    category,
    vendor: String(ext.vendor ?? '').trim(),
    note: String(ext.note ?? '').trim(),
    raw_text: raw,
  },
}];

const zone = 'Asia/Riyadh';
const now = DateTime.now().setZone(zone);
const todayKey = now.toISODate();
const monthKey = now.toFormat('yyyy-MM');
const round = (n) => Math.round(n * 100) / 100;

const rows = $input.all()
  .map((i) => i.json)
  .filter((r) => r && r.id !== undefined && r.id !== null);

const entries = rows
  .map((r) => {
    const d = DateTime.fromISO(String(r.spent_at ?? ''), { zone });
    return {
      id: r.id,
      spent_at: d.isValid ? d.toISODate() : null,
      amount: Number(r.amount) || 0,
      currency: r.currency || 'SAR',
      direction: r.direction === 'income' ? 'income' : 'expense',
      category: r.category || 'أخرى',
      vendor: r.vendor || '',
      note: r.note || '',
      raw_text: r.raw_text || '',
      created_at: r.createdAt ?? null,
    };
  })
  .sort((a, b) => String(b.spent_at).localeCompare(String(a.spent_at)) || Number(b.id) - Number(a.id));

const isExp = (e) => e.direction === 'expense';
const inMonth = (e) => typeof e.spent_at === 'string' && e.spent_at.startsWith(monthKey);
const sum = (list) => round(list.reduce((s, e) => s + e.amount, 0));

const byCategory = {};
for (const e of entries) {
  if (!isExp(e) || !inMonth(e)) continue;
  byCategory[e.category] = (byCategory[e.category] || 0) + e.amount;
}

const expMonth = sum(entries.filter((e) => isExp(e) && inMonth(e)));
const incMonth = sum(entries.filter((e) => !isExp(e) && inMonth(e)));

return [{
  json: {
    entries,
    currency: 'SAR',
    totals: {
      today: sum(entries.filter((e) => isExp(e) && e.spent_at === todayKey)),
      month: expMonth,
      income_month: incMonth,
      net_month: round(incMonth - expMonth),
      count: entries.length,
      by_category: Object.entries(byCategory)
        .map(([category, amount]) => ({ category, amount: round(amount) }))
        .sort((a, b) => b.amount - a.amount),
    },
  },
}];

